-- Notifications are generated by database events, not by client inserts.
CREATE TABLE public.notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  type text NOT NULL CHECK (type IN (
    'application_created', 'application_accepted',
    'application_rejected', 'member_joined'
  )),
  title text NOT NULL,
  message text NOT NULL,
  related_project_id uuid REFERENCES public.projects(id) ON DELETE SET NULL,
  is_read boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE INDEX notifications_user_created_idx
  ON public.notifications (user_id, created_at DESC, id DESC);
CREATE INDEX notifications_user_unread_idx
  ON public.notifications (user_id) WHERE is_read = false;

ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.notifications FROM PUBLIC, anon, authenticated;
GRANT SELECT, UPDATE (is_read) ON public.notifications TO authenticated;

CREATE POLICY "Users can read their notifications"
ON public.notifications FOR SELECT TO authenticated
USING (user_id = auth.uid());

CREATE POLICY "Users can mark their notifications read"
ON public.notifications FOR UPDATE TO authenticated
USING (user_id = auth.uid())
WITH CHECK (user_id = auth.uid());

CREATE FUNCTION public.create_project_notifications()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_project_title text;
  v_owner_id uuid;
  v_role text;
BEGIN
  SELECT project.title, project.owner_id
  INTO v_project_title, v_owner_id
  FROM public.projects AS project
  WHERE project.id = NEW.project_id;

  IF TG_TABLE_NAME = 'project_applications' THEN
    v_role := NULLIF(btrim(NEW.role_applied_for), '');
    IF TG_OP = 'INSERT' THEN
      INSERT INTO public.notifications
        (user_id, type, title, message, related_project_id)
      VALUES (
        v_owner_id, 'application_created', 'Новая заявка',
        format('На проект «%s» подана заявка%s.', v_project_title,
          CASE WHEN v_role IS NULL THEN '' ELSE format(' на роль %s', v_role) END),
        NEW.project_id
      );
    ELSIF OLD.status = 'pending' AND NEW.status = 'accepted' THEN
      INSERT INTO public.notifications
        (user_id, type, title, message, related_project_id)
      VALUES (
        NEW.user_id, 'application_accepted', 'Заявка принята',
        format('Ваша заявка в проект «%s»%s принята.', v_project_title,
          CASE WHEN v_role IS NULL THEN '' ELSE format(' на роль %s', v_role) END),
        NEW.project_id
      );
    ELSIF OLD.status = 'pending' AND NEW.status = 'rejected' THEN
      INSERT INTO public.notifications
        (user_id, type, title, message, related_project_id)
      VALUES (
        NEW.user_id, 'application_rejected', 'Заявка отклонена',
        format('Ваша заявка в проект «%s»%s отклонена.', v_project_title,
          CASE WHEN v_role IS NULL THEN '' ELSE format(' на роль %s', v_role) END),
        NEW.project_id
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.create_project_notifications() FROM PUBLIC, anon, authenticated;

CREATE TRIGGER notify_project_owner_on_application
AFTER INSERT ON public.project_applications
FOR EACH ROW EXECUTE FUNCTION public.create_project_notifications();

CREATE TRIGGER notify_applicant_on_decision
AFTER UPDATE OF status ON public.project_applications
FOR EACH ROW
WHEN (OLD.status = 'pending' AND NEW.status IN ('accepted', 'rejected'))
EXECUTE FUNCTION public.create_project_notifications();

-- accept_project_application also inserts project_members; a membership trigger
-- would send the same recipient a second notification for that acceptance.

-- Enable filtered Postgres Changes when the Supabase publication exists.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_publication
    WHERE pubname = 'supabase_realtime' AND NOT puballtables
  ) AND NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public' AND tablename = 'notifications'
  ) THEN
    EXECUTE 'ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications';
  END IF;
END;
$$;
